    _SOURCE = 'from __future__ import annotations\n\n# ======================================================================\n# multilevel_table/header.py\n# ======================================================================\n"""\nHeader tree model for the multilevel table widget.\n\nHierarchy rules\n---------------\n- A node is a **leaf** if it was defined with no children (original leaf)\n  OR if it has been merged (children hidden).\n- A node **can be merged** if it is currently internal and every one of its\n  direct children is currently a leaf.  Merges therefore proceed bottom-up.\n- A node **can be split** only if it was previously merged (not an original\n  leaf — those have nothing to restore).\n"""\n\n\nimport re\nimport uuid\nfrom dataclasses import dataclass, field\nfrom typing import Iterator\n\n\n# ---------------------------------------------------------------------------\n# Core node\n# ---------------------------------------------------------------------------\n\n@dataclass\nclass HeaderNode:\n    key: str\n    label: str\n    children: list[HeaderNode] = field(default_factory=list)\n    merged: bool = False\n\n    # --- State ---\n\n    @property\n    def is_leaf(self) -> bool:\n        """Leaf when originally childless or currently merged."""\n        return self.merged or not self.children\n\n    @property\n    def is_original_leaf(self) -> bool:\n        """True if the node was defined without children at creation."""\n        return not self.children\n\n    @property\n    def can_merge(self) -> bool:\n        """\n        True when every direct child is currently a leaf.\n        (An original leaf and already-merged nodes both satisfy this.)\n        """\n        return not self.is_leaf and all(c.is_leaf for c in self.children)\n\n    @property\n    def can_split(self) -> bool:\n        """Only nodes that were explicitly merged can be split."""\n        return self.merged  # original leaves have nothing to restore\n\n    # --- Mutations ---\n\n    def merge(self) -> None:\n        """Collapse all direct children; this node becomes a leaf."""\n        if not self.can_merge:\n            if self.is_leaf:\n                reason = "already a leaf"\n            else:\n                non_leaves = [c.key for c in self.children if not c.is_leaf]\n                reason = f"children that are not yet leaves: {non_leaves}"\n            raise ValueError(f"Cannot merge \'{self.key}\': {reason}")\n        self.merged = True\n\n    def split(self) -> None:\n        """Re-expose direct children; this node becomes internal again."""\n        if not self.can_split:\n            raise ValueError(\n                f"Cannot split \'{self.key}\': "\n                + ("original leaf — no children to restore"\n                   if self.is_original_leaf else "not currently merged")\n            )\n        self.merged = False\n\n    def relabel(self, new_label: str) -> None:\n        """\n        Change the display label of this node.\n\n        Valid on any node at any time — no tree-state constraints.\n        The key is unaffected; it remains the stable identifier used by\n        JavaScript and the rest of the Python model.\n        """\n        if not new_label.strip():\n            raise ValueError(f"Cannot relabel \'{self.key}\': label must not be empty")\n        self.label = new_label\n\n    # --- Traversal ---\n\n    def leaves(self) -> Iterator[HeaderNode]:\n        """Yield current leaf nodes in display order."""\n        if self.is_leaf:\n            yield self\n        else:\n            for child in self.children:\n                yield from child.leaves()\n\n    def all_nodes(self) -> Iterator[HeaderNode]:\n        """Yield every node in the full subtree, ignoring merged state."""\n        yield self\n        for child in self.children:\n            yield from child.all_nodes()\n\n    def find(self, key: str) -> HeaderNode | None:\n        """Return the first node matching *key* in this subtree, or None."""\n        for node in self.all_nodes():\n            if node.key == key:\n                return node\n        return None\n\n    # --- Metrics ---\n\n    def leaf_count(self) -> int:\n        return sum(1 for _ in self.leaves())\n\n    def visible_depth(self) -> int:\n        """\n        Depth of the *currently visible* tree.\n        A merged or original leaf has depth 1.\n        """\n        if self.is_leaf:\n            return 1\n        return 1 + max(c.visible_depth() for c in self.children)\n\n    def full_depth(self) -> int:\n        """Depth of the complete tree, ignoring merged state."""\n        if not self.children:\n            return 1\n        return 1 + max(c.full_depth() for c in self.children)\n\n    # --- Serialisation ---\n\n    def to_dict(self) -> dict:\n        """\n        Serialise for JS transport.\n        Children are always included (the JS needs them to handle splits),\n        but the JS must respect `merged` when deciding what to render.\n        """\n        return {\n            "key": self.key,\n            "label": self.label,\n            "merged": self.merged,\n            "isLeaf": self.is_leaf,\n            "canMerge": self.can_merge,\n            "canSplit": self.can_split,\n            "children": [c.to_dict() for c in self.children],\n        }\n\n    @classmethod\n    def from_dict(cls, data: dict) -> HeaderNode:\n        return cls(\n            key=data["key"],\n            label=data["label"],\n            merged=data.get("merged", False),\n            children=[cls.from_dict(c) for c in data.get("children", [])],\n        )\n\n    def __repr__(self) -> str:\n        state = " [merged]" if self.merged else (" [leaf]" if self.is_original_leaf else "")\n        return f"HeaderNode({self.key!r}{state}, children={len(self.children)})"\n\n\n# ---------------------------------------------------------------------------\n# Builder shorthand\n# ---------------------------------------------------------------------------\n\ndef H(\n    label: str,\n    children: list[HeaderNode] | None = None,\n    *,\n    key: str | None = None,\n) -> HeaderNode:\n    """\n    Fluent HeaderNode constructor.\n\n    Usage::\n\n        H("Hardware", [\n            H("Laptops", [H("Pro 13in", key="pro_13"), H("Air", key="air")],\n              key="laptops"),\n        ], key="hardware")\n\n    Keys default to a label-derived slug + short UUID suffix to guarantee\n    uniqueness across siblings with identical labels (e.g. two "Q1" nodes).\n    Supply an explicit *key* wherever stable, human-readable identifiers matter\n    (tests, serialisation round-trips, etc.).\n    """\n    return HeaderNode(\n        key=key if key is not None else _make_key(label),\n        label=label,\n        children=children or [],\n    )\n\n\ndef _make_key(label: str) -> str:\n    slug = re.sub(r"[^\\w]+", "_", label.lower()).strip("_")\n    return f"{slug}_{uuid.uuid4().hex[:4]}"\n\n\n# ---------------------------------------------------------------------------\n# Forest utilities  (a "forest" is a list[HeaderNode] of root nodes)\n# ---------------------------------------------------------------------------\n\ndef find_node(roots: list[HeaderNode], key: str) -> HeaderNode | None:\n    """Search across all roots for *key*."""\n    for root in roots:\n        result = root.find(key)\n        if result is not None:\n            return result\n    return None\n\n\ndef all_leaves(roots: list[HeaderNode]) -> list[HeaderNode]:\n    """Ordered list of current leaves across the forest."""\n    return [leaf for root in roots for leaf in root.leaves()]\n\n\ndef leaf_key_paths(roots: list[HeaderNode]) -> list[list[str]]:\n    """\n    Root-to-leaf key path for each current leaf, in display order.\n\n    For the initial column tree this yields e.g.::\n\n        ["region", "emea", "uk", "uk_rev"]\n        ["region", "emea", "uk", "uk_units"]\n        ...\n\n    After merging UK, its path stops at the merged node::\n\n        ["region", "emea", "uk"]\n\n    The widget hands these paths to the user\'s calculate callback, so the\n    callback always sees the current structure — a merged leaf is identified\n    by the path ending at the merged node.\n    """\n    paths: list[list[str]] = []\n\n    def walk(node: HeaderNode, prefix: list[str]) -> None:\n        path = prefix + [node.key]\n        if node.is_leaf:\n            paths.append(path)\n        else:\n            for child in node.children:\n                walk(child, path)\n\n    for root in roots:\n        walk(root, [])\n    return paths\n\n\ndef mergeable_nodes(roots: list[HeaderNode]) -> list[HeaderNode]:\n    """All nodes that are currently valid merge targets."""\n    return [n for root in roots for n in root.all_nodes() if n.can_merge]\n\n\ndef splittable_nodes(roots: list[HeaderNode]) -> list[HeaderNode]:\n    """All nodes that are currently valid split targets."""\n    return [n for root in roots for n in root.all_nodes() if n.can_split]\n\n\ndef forest_visible_depth(roots: list[HeaderNode]) -> int:\n    """\n    Maximum visible depth across all roots.\n    This determines how many header rows (or columns) the rendered table needs.\n    """\n    return max((r.visible_depth() for r in roots), default=0)\n\n\ndef forest_full_depth(roots: list[HeaderNode]) -> int:\n    """Maximum full depth — useful for pre-allocating render space."""\n    return max((r.full_depth() for r in roots), default=0)\n\n\ndef serialize_forest(roots: list[HeaderNode]) -> list[dict]:\n    return [r.to_dict() for r in roots]\n\n\ndef deserialize_forest(data: list[dict]) -> list[HeaderNode]:\n    return [HeaderNode.from_dict(d) for d in data]\n\n# ======================================================================\n# multilevel_table/spans.py\n# ======================================================================\n"""\nSpan computation for multilevel header rendering.\n\nGiven a forest of HeaderNodes, this module computes the colspan and rowspan\nthat each visible node needs as an HTML <th> element.\n\nTwo orientations are supported:\n\n  compute_col_header_grid  —  column headers rendered as rows above the data.\n                              Depth maps to rows; leaf position maps to columns.\n\n  compute_row_header_grid  —  row headers rendered as columns to the left.\n                              Depth maps to columns; leaf position maps to rows.\n\nThe algorithms are identical in structure; only which axis carries depth and\nwhich carries leaf position differs.\n\nInvariant\n---------\nFor any valid grid, the sum of (rowspan × colspan) across all cells equals\nexactly (grid.depth × grid.leaf_count).  Every cell in the header area is\ncovered by exactly one span — no gaps, no overlaps.\n"""\n\n\nfrom dataclasses import dataclass\n\n\n\n# ---------------------------------------------------------------------------\n# Data structures\n# ---------------------------------------------------------------------------\n\n@dataclass\nclass SpanCell:\n    """\n    A single rendered header cell with its grid position and span values.\n\n    row, col    — zero-indexed position in the full header grid.\n    rowspan     — number of grid rows this cell occupies.\n    colspan     — number of grid columns this cell occupies.\n\n    For column headers  the grid has `depth` rows and `leaf_count` columns.\n    For row headers     the grid has `leaf_count` rows and `depth` columns.\n    """\n    key: str\n    label: str\n    row: int\n    col: int\n    rowspan: int\n    colspan: int\n    is_leaf: bool\n    can_merge: bool\n    can_split: bool\n\n    def to_dict(self) -> dict:\n        return {\n            "key": self.key,\n            "label": self.label,\n            "row": self.row,\n            "col": self.col,\n            "rowspan": self.rowspan,\n            "colspan": self.colspan,\n            "isLeaf": self.is_leaf,\n            "canMerge": self.can_merge,\n            "canSplit": self.can_split,\n        }\n\n\n@dataclass\nclass HeaderGrid:\n    """\n    The complete set of span cells for one header axis, plus dimensions.\n\n    depth       — number of header rows (col axis) or header columns (row axis).\n    leaf_count  — number of data columns (col axis) or data rows (row axis).\n    """\n    cells: list[SpanCell]\n    depth: int\n    leaf_count: int\n\n    # --- Lookup helpers ---\n\n    def find_cell(self, key: str) -> SpanCell | None:\n        """Return the cell for *key*, or None."""\n        for cell in self.cells:\n            if cell.key == key:\n                return cell\n        return None\n\n    def cells_at_row(self, row: int) -> list[SpanCell]:\n        """All cells whose top edge is at *row*."""\n        return [c for c in self.cells if c.row == row]\n\n    def cells_at_col(self, col: int) -> list[SpanCell]:\n        """All cells whose left edge is at *col*."""\n        return [c for c in self.cells if c.col == col]\n\n    @property\n    def total_area(self) -> int:\n        """Expected sum of rowspan × colspan — equals depth × leaf_count."""\n        return self.depth * self.leaf_count\n\n    @property\n    def covered_area(self) -> int:\n        """Actual sum of rowspan × colspan across all cells."""\n        return sum(c.rowspan * c.colspan for c in self.cells)\n\n    def to_dict(self) -> dict:\n        return {\n            "cells": [c.to_dict() for c in self.cells],\n            "depth": self.depth,\n            "leafCount": self.leaf_count,\n        }\n\n\n# ---------------------------------------------------------------------------\n# Core algorithms\n# ---------------------------------------------------------------------------\n\ndef compute_col_header_grid(roots: list[HeaderNode]) -> HeaderGrid:\n    """\n    Column headers — rendered as horizontal rows above the data table.\n\n    Each node sits in the row corresponding to its depth.  Its colspan is the\n    number of leaves beneath it.  If it is a leaf it receives rowspan equal to\n    the remaining depth below it (so it stretches down to the bottom of the\n    header band), otherwise rowspan is 1.\n\n    Example — initial col_roots (D=4, 8 leaves):\n\n        row 0  Region  ·············· colspan=8\n        row 1  EMEA ···· colspan=4   APAC ···· colspan=4\n        row 2  UK·· Germany··        Japan·· Australia··\n        row 3  Rev Units Rev Units   Rev Units Rev  Units\n    """\n    D = forest_visible_depth(roots)\n    cells: list[SpanCell] = []\n\n    def walk(node: HeaderNode, depth: int, col_offset: int) -> None:\n        colspan = node.leaf_count()\n        rowspan = D - depth + 1 if node.is_leaf else 1\n\n        cells.append(SpanCell(\n            key=node.key,\n            label=node.label,\n            row=depth - 1,\n            col=col_offset,\n            rowspan=rowspan,\n            colspan=colspan,\n            is_leaf=node.is_leaf,\n            can_merge=node.can_merge,\n            can_split=node.can_split,\n        ))\n\n        if not node.is_leaf:\n            child_col = col_offset\n            for child in node.children:\n                walk(child, depth + 1, child_col)\n                child_col += child.leaf_count()\n\n    col_offset = 0\n    for root in roots:\n        walk(root, 1, col_offset)\n        col_offset += root.leaf_count()\n\n    return HeaderGrid(\n        cells=cells,\n        depth=D,\n        leaf_count=len(all_leaves(roots)),\n    )\n\n\ndef compute_row_header_grid(roots: list[HeaderNode]) -> HeaderGrid:\n    """\n    Row headers — rendered as vertical columns to the left of the data table.\n\n    Depth maps to columns; leaf position maps to rows.  A node\'s rowspan is\n    the number of leaves beneath it.  If it is a leaf its colspan stretches\n    right to the last header column (D - depth + 1), otherwise colspan is 1.\n\n    Example — initial row_roots (D=4, 8 leaves):\n\n        col 0       col 1       col 2         col 3\n        Division    Hardware    Laptops       Pro 13in   rowspan=1\n                                              Pro 15in   rowspan=1\n                                              Air        rowspan=1\n                                Tablets       Standard   rowspan=1\n                                              Plus       rowspan=1\n                    Software    Productivity  Basic      rowspan=1\n                                              Pro        rowspan=1\n                                Security      Shield     rowspan=1 colspan=2\n    """\n    D = forest_visible_depth(roots)\n    cells: list[SpanCell] = []\n\n    def walk(node: HeaderNode, depth: int, row_offset: int) -> None:\n        rowspan = node.leaf_count()\n        colspan = D - depth + 1 if node.is_leaf else 1\n\n        cells.append(SpanCell(\n            key=node.key,\n            label=node.label,\n            row=row_offset,\n            col=depth - 1,\n            rowspan=rowspan,\n            colspan=colspan,\n            is_leaf=node.is_leaf,\n            can_merge=node.can_merge,\n            can_split=node.can_split,\n        ))\n\n        if not node.is_leaf:\n            child_row = row_offset\n            for child in node.children:\n                walk(child, depth + 1, child_row)\n                child_row += child.leaf_count()\n\n    row_offset = 0\n    for root in roots:\n        walk(root, 1, row_offset)\n        row_offset += root.leaf_count()\n\n    return HeaderGrid(\n        cells=cells,\n        depth=D,\n        leaf_count=len(all_leaves(roots)),\n    )\n\n# ======================================================================\n# multilevel_table/fields.py\n# ======================================================================\n"""\nField-based hierarchy construction (the model behind a pivot-style\ndrag-and-drop field selector).\n\nA `Field` is a dimension with a name and a list of members. `build_forest`\ntakes an ordered list of fields and produces the cross-product header forest:\nthe first field\'s members are the top-level nodes, the next field\'s members\nnest under each, and so on. Each field may start collapsed (`start_merged`),\nproducing nodes that are pre-merged but still splittable.\n\nThis is a convenience layer over the explicit HeaderNode trees. It generates\n*regular* cross-product hierarchies — every parent at a given level has the\nsame child members. Irregular hierarchies (different members under different\nparents, like the hand-built dev example) still need explicit H() trees.\n"""\n\n\nimport re\nfrom dataclasses import dataclass\n\n\n\n@dataclass\nclass Field:\n    name: str                 # dimension name, e.g. "Region" (shown as an axis caption)\n    members: list[str]        # member labels, e.g. ["EMEA", "APAC"]\n    key: str | None = None    # stable key prefix; defaults to a slug of name\n    start_merged: bool = False  # nodes at this level start collapsed (but splittable)\n\n    def resolved_key(self) -> str:\n        return self.key or _slug(self.name)\n\n\ndef _slug(s: str) -> str:\n    return re.sub(r"[^\\w]+", "_", s.lower()).strip("_")\n\n\ndef build_forest(fields: list[Field]) -> list[HeaderNode]:\n    """\n    Build a cross-product header forest from an ordered list of fields.\n\n    Example::\n\n        build_forest([\n            Field("Region", ["EMEA", "APAC"]),\n            Field("Metric", ["Revenue", "Units"]),\n        ])\n\n    yields two roots (EMEA, APAC), each with two children (Revenue, Units) —\n    four leaves total.\n\n    `start_merged` only takes effect on fields that have a level beneath them\n    (a deepest-level field has nothing to merge, so the flag is ignored there).\n    """\n    if not fields:\n        return []\n\n    field_keys = [f.resolved_key() for f in fields]\n\n    def build(level: int, parent_key: str) -> list[HeaderNode]:\n        f = fields[level]\n        fkey = field_keys[level]\n        nodes: list[HeaderNode] = []\n        for member in f.members:\n            mslug = _slug(member)\n            key = f"{parent_key}.{fkey}_{mslug}" if parent_key else f"{fkey}_{mslug}"\n            has_deeper = level + 1 < len(fields)\n            children = build(level + 1, key) if has_deeper else []\n            nodes.append(HeaderNode(\n                key=key,\n                label=member,\n                children=children,\n                merged=f.start_merged and has_deeper,\n            ))\n        return nodes\n\n    return build(0, "")\n\n\ndef field_captions(fields: list[Field]) -> list[str]:\n    """The ordered field names, for display as axis captions (pivot-style)."""\n    return [f.name for f in fields]\n\n# ======================================================================\n# multilevel_table/examples.py\n# ======================================================================\n"""\nThe development hierarchy and an example SVG `calculate`, shared by the demo\nnotebooks and the browser check.\n\n    from multilevel_table.examples import example_headers, example_calculate\n    rows, cols = example_headers()\n    table = MultilevelTable(rows, cols, example_calculate)\n"""\n\n\nimport zlib\n\n\nTILE_W, TILE_H = 96, 48\n\n\ndef example_headers() -> tuple[HeaderNode, HeaderNode]:\n    """Rows: Division > Category > Product > Variant (8 leaves).\n    Columns: Region > Country > Metric (8 leaves)."""\n    rows = H("Division", [\n        H("Hardware", [\n            H("Laptops", [\n                H("Pro 13in", key="pro_13"),\n                H("Pro 15in", key="pro_15"),\n                H("Air", key="air"),\n            ], key="laptops"),\n            H("Tablets", [\n                H("Standard", key="tab_std"),\n                H("Plus", key="tab_plus"),\n            ], key="tablets"),\n        ], key="hardware"),\n        H("Software", [\n            H("Productivity", [\n                H("Basic", key="prod_basic"),\n                H("Pro", key="prod_pro"),\n            ], key="productivity"),\n            H("Security", [H("Shield", key="shield")], key="security"),\n        ], key="software"),\n    ], key="division")\n\n    cols = H("Region", [\n        H("EMEA", [\n            H("United Kingdom", [H("Revenue", key="uk_rev"), H("Units", key="uk_units")], key="uk"),\n            H("Germany", [H("Revenue", key="de_rev"), H("Units", key="de_units")], key="germany"),\n        ], key="emea"),\n        H("APAC", [\n            H("Japan", [H("Revenue", key="jp_rev"), H("Units", key="jp_units")], key="japan"),\n            H("Australia", [H("Revenue", key="au_rev"), H("Units", key="au_units")], key="australia"),\n        ], key="apac"),\n    ], key="region")\n    return rows, cols\n\n\ndef _score(*parts: str) -> float:\n    """Deterministic pseudo-value in [0, 1) from a set of keys."""\n    return (zlib.crc32("/".join(parts).encode()) % 1000) / 1000\n\n\ndef example_calculate(row_path: list[str], col_path: list[str]) -> str:\n    """\n    A tile per cell, drawn in a viewBox the same shape as the tile (96 x 48)\n    so it fills the cell edge to edge.\n\n    - Revenue leaves: a horizontal bar.\n    - Units leaves:   five small columns.\n    - Merged columns (the path stops above the metric level): a summary bar\n      in a second colour, showing the cell really is recalculated on merge.\n    """\n    leaf = col_path[-1]\n    v = _score(row_path[-1], leaf)\n    w, h = TILE_W, TILE_H\n\n    if leaf.endswith("_rev"):\n        bar = 8 + v * (w - 16)\n        return (\n            f"<svg viewBox=\'0 0 {w} {h}\' preserveAspectRatio=\'none\'>"\n            f"<rect width=\'{w}\' height=\'{h}\' fill=\'#eef3f2\'/>"\n            f"<rect x=\'8\' y=\'18\' width=\'{bar:.1f}\' height=\'12\' rx=\'2\' fill=\'#16706b\'/>"\n            f"</svg>"\n        )\n\n    if leaf.endswith("_units"):\n        cols = []\n        for i in range(5):\n            ch = 6 + _score(row_path[-1], leaf, str(i)) * (h - 14)\n            cols.append(f"<rect x=\'{12 + i * 15}\' y=\'{h - 4 - ch:.1f}\' width=\'10\' height=\'{ch:.1f}\' fill=\'#5b6fb3\'/>")\n        return (\n            f"<svg viewBox=\'0 0 {w} {h}\' preserveAspectRatio=\'none\'>"\n            f"<rect width=\'{w}\' height=\'{h}\' fill=\'#f0f1f7\'/>{\'\'.join(cols)}</svg>"\n        )\n\n    # A merged column: one summary bar plus the name of what was merged.\n    bar = 8 + v * (w - 16)\n    return (\n        f"<svg viewBox=\'0 0 {w} {h}\' preserveAspectRatio=\'none\'>"\n        f"<rect width=\'{w}\' height=\'{h}\' fill=\'#f7efe6\'/>"\n        f"<rect x=\'8\' y=\'20\' width=\'{bar:.1f}\' height=\'16\' rx=\'2\' fill=\'#b0602a\'/>"\n        f"<text x=\'8\' y=\'14\' font-size=\'9\' font-family=\'sans-serif\' fill=\'#6b4a2e\'>Σ {leaf}</text>"\n        f"</svg>"\n    )\n\n# ======================================================================\n# multilevel_table/widget.py\n# ======================================================================\n"""\nThe MultilevelTable anywidget (v2).\n\nColumns carry a mergeable hierarchy; rows carry a fixed hierarchy with one\ndata row per row leaf.  Every data cell is the output of a user-supplied\n``calculate(row_path, col_path)`` callback — normally an SVG string.\n\nState flow\n----------\nPython owns the header trees and computes everything the browser draws.\nThe browser changes exactly two pieces of state, both as ordinary synced\ntraits (``model.set`` + ``save_changes``), which is the path marimo watches\nfor reactivity:\n\n    col_merged   list of column keys the user wants merged\n    selected     {"row": [...keys], "col": [...keys]} or None\n\nPython observes those traits, validates them against the tree, recomputes,\nand writes back the corrected state.\n\n    browser click ──▶ model.set("col_merged" | "selected")\n                           │\n                           ▼\n          Python observer: apply merges/splits, recompute grids + data\n                           │\n                           ▼\n            synced traits update ──▶ browser re-renders\n\nIn marimo, wrap the widget with ``mo.ui.anywidget(table)``; ``widget.value``\nis then a dict of every synced trait, e.g. ``widget.value["selected"]``.\n"""\n\n\nimport pathlib\nfrom typing import Any, Callable\n\nimport anywidget\nimport traitlets\n\n\n\n# (row_path, col_path) -> SVG string, number, text or None.\nCalculateFn = Callable[[list[str], list[str]], Any]\n\n\nclass MultilevelTable(anywidget.AnyWidget):\n    _esm = \'// MultilevelTable v2 renderer — a single CSS Grid.\\n//\\n// Python sends: col_grid, row_grid (span cells), row_paths, col_paths,\\n// data (R x C values), cell_width, cell_height.\\n// The browser sets only two traits: col_merged (merge/split) and selected.\\n//\\n// Grid layout (1-indexed lines):\\n//   columns: [rowDepth header cols, max-content] [C data cols, cell_width]\\n//   rows:    [colDepth header rows, auto]        [R data rows, cell_height]\\n\\nconst SVG_NS = "http://www.w3.org/2000/svg";\\n\\nfunction el(tag, cls) {\\n  const e = document.createElement(tag);\\n  if (cls) e.className = cls;\\n  return e;\\n}\\n\\nfunction place(node, col, colspan, row, rowspan) {\\n  node.style.gridColumn = `${col} / span ${colspan}`;\\n  node.style.gridRow = `${row} / span ${rowspan}`;\\n}\\n\\nfunction samePath(a, b) {\\n  return Array.isArray(a) && Array.isArray(b) && a.length === b.length && a.every((k, i) => k === b[i]);\\n}\\n\\n// ---------------------------------------------------------------------------\\n// Cell content\\n// ---------------------------------------------------------------------------\\n\\nfunction fillCell(td, value) {\\n  if (value === null || value === undefined || value === "") {\\n    td.classList.add("mlt-empty");\\n    return;\\n  }\\n  if (typeof value === "string" && value.trimStart().startsWith("<svg")) {\\n    // The XML parser needs the SVG namespace; add it if the author left it off.\\n    let markup = value.trim();\\n    if (!/^<svg[^>]*\\\\sxmlns=/.test(markup)) markup = markup.replace(/^<svg/, `<svg xmlns="${SVG_NS}"`);\\n    const doc = new DOMParser().parseFromString(markup, "image/svg+xml");\\n    const root = doc.documentElement;\\n    if (root && root.namespaceURI === SVG_NS && !doc.querySelector("parsererror")) {\\n      td.appendChild(document.importNode(root, true));\\n      return;\\n    }\\n    td.classList.add("mlt-bad");\\n    td.title = "Invalid SVG";\\n    td.textContent = "!";\\n    return;\\n  }\\n  const span = el("span", "mlt-text");\\n  span.textContent = String(value);\\n  td.appendChild(span);\\n}\\n\\n// ---------------------------------------------------------------------------\\n// Headers\\n// ---------------------------------------------------------------------------\\n\\nfunction headerCell(cell, axis) {\\n  const level = Math.min(axis === "col" ? cell.row : cell.col, 3);\\n  const h = el("div", `mlt-h mlt-h-${axis} mlt-lvl-${level}`);\\n  h.dataset.key = cell.key;\\n  if (cell.isLeaf) h.classList.add("mlt-leaf");\\n\\n  const label = el("span", "mlt-label");\\n  label.textContent = cell.label;\\n  h.appendChild(label);\\n\\n  if (axis === "col" && (cell.canMerge || cell.canSplit)) {\\n    h.classList.add(cell.canSplit ? "mlt-splittable" : "mlt-mergeable");\\n    const glyph = el("span", "mlt-glyph");\\n    glyph.textContent = cell.canSplit ? "+" : "–";\\n    glyph.setAttribute("aria-hidden", "true");\\n    h.appendChild(glyph);\\n    h.title = cell.canSplit ? `Split ${cell.label}` : `Merge ${cell.label}`;\\n  }\\n  return h;\\n}\\n\\n// ---------------------------------------------------------------------------\\n// Render\\n// ---------------------------------------------------------------------------\\n\\nfunction render({ model, el: root }) {\\n  root.classList.add("mlt-root");\\n  const scroll = el("div", "mlt-scroll");\\n  root.appendChild(scroll);\\n\\n  let cellNodes = [];   // [r][c] -> div, for cheap selection updates\\n\\n  function applySize() {\\n    root.style.setProperty("--mlt-cell-w", `${model.get("cell_width")}px`);\\n    root.style.setProperty("--mlt-cell-h", `${model.get("cell_height")}px`);\\n  }\\n\\n  function toggleMerge(cell) {\\n    const merged = new Set(model.get("col_merged") || []);\\n    if (cell.canSplit) merged.delete(cell.key);\\n    else if (cell.canMerge) merged.add(cell.key);\\n    else return;\\n    model.set("col_merged", [...merged]);\\n    model.save_changes();\\n  }\\n\\n  function selectCell(r, c) {\\n    const rowPath = model.get("row_paths")[r];\\n    const colPath = model.get("col_paths")[c];\\n    const cur = model.get("selected");\\n    const next = cur && samePath(cur.row, rowPath) && samePath(cur.col, colPath)\\n      ? null\\n      : { row: rowPath, col: colPath };\\n    model.set("selected", next);\\n    model.save_changes();\\n  }\\n\\n  function paintSelection() {\\n    const sel = model.get("selected");\\n    const rowPaths = model.get("row_paths");\\n    const colPaths = model.get("col_paths");\\n    for (let r = 0; r < cellNodes.length; r++) {\\n      const isRow = !!sel && samePath(sel.row, rowPaths[r]);\\n      for (let c = 0; c < cellNodes[r].length; c++) {\\n        cellNodes[r][c].classList.toggle("mlt-selected", isRow && samePath(sel.col, colPaths[c]));\\n      }\\n    }\\n  }\\n\\n  // Sticky header rows/columns need cumulative offsets, otherwise every\\n  // header row would stick at top:0 on top of the one above it.\\n  function pinHeaders(grid) {\\n    for (const h of grid.querySelectorAll(".mlt-h-col")) h.style.top = `${h.offsetTop}px`;\\n    for (const h of grid.querySelectorAll(".mlt-h-row")) h.style.left = `${h.offsetLeft}px`;\\n  }\\n\\n  function draw() {\\n    applySize();\\n    const colGrid = model.get("col_grid");\\n    const rowGrid = model.get("row_grid");\\n    const data = model.get("data") || [];\\n    if (!colGrid || !colGrid.cells || !rowGrid || !rowGrid.cells) return;\\n\\n    const colDepth = colGrid.depth, C = colGrid.leafCount;\\n    const rowDepth = rowGrid.depth, R = rowGrid.leafCount;\\n    if (!C || !R || !colDepth || !rowDepth) {        // repeat(0, …) is invalid CSS\\n      const note = el("div", "mlt-note");\\n      note.textContent = "No rows or columns to show.";\\n      scroll.replaceChildren(note);\\n      cellNodes = [];\\n      return;\\n    }\\n\\n    const grid = el("div", "mlt-grid");\\n    grid.style.gridTemplateColumns =\\n      `repeat(${rowDepth}, max-content) repeat(${C}, var(--mlt-cell-w))`;\\n    grid.style.gridTemplateRows =\\n      `repeat(${colDepth}, auto) repeat(${R}, var(--mlt-cell-h))`;\\n\\n    const frag = document.createDocumentFragment();\\n\\n    const corner = el("div", "mlt-corner");\\n    place(corner, 1, rowDepth, 1, colDepth);\\n    frag.appendChild(corner);\\n\\n    for (const cell of colGrid.cells) {\\n      const h = headerCell(cell, "col");\\n      place(h, rowDepth + cell.col + 1, cell.colspan, cell.row + 1, cell.rowspan);\\n      if (cell.canMerge || cell.canSplit) h.addEventListener("click", () => toggleMerge(cell));\\n      frag.appendChild(h);\\n    }\\n\\n    for (const cell of rowGrid.cells) {\\n      const h = headerCell(cell, "row");\\n      place(h, cell.col + 1, cell.colspan, colDepth + cell.row + 1, cell.rowspan);\\n      frag.appendChild(h);\\n    }\\n\\n    cellNodes = [];\\n    for (let r = 0; r < R; r++) {\\n      const rowNodes = [];\\n      for (let c = 0; c < C; c++) {\\n        const d = el("div", "mlt-cell");\\n        d.style.gridColumn = `${rowDepth + c + 1}`;\\n        d.style.gridRow = `${colDepth + r + 1}`;\\n        fillCell(d, data[r] ? data[r][c] : null);\\n        d.addEventListener("click", () => selectCell(r, c));\\n        rowNodes.push(d);\\n        frag.appendChild(d);\\n      }\\n      cellNodes.push(rowNodes);\\n    }\\n\\n    grid.appendChild(frag);\\n    scroll.replaceChildren(grid);\\n    paintSelection();\\n    requestAnimationFrame(() => pinHeaders(grid));\\n  }\\n\\n  // One sync changes several traits at once; coalesce them into one redraw.\\n  let drawQueued = false;\\n  function scheduleDraw() {\\n    if (drawQueued) return;\\n    drawQueued = true;\\n    queueMicrotask(() => { drawQueued = false; draw(); });\\n  }\\n\\n  // One event name per model.on call: marimo\\\'s model does not accept the\\n  // space-separated list that Backbone does.\\n  const resize = () => {\\n    applySize();\\n    const grid = scroll.firstChild;\\n    if (grid) requestAnimationFrame(() => pinHeaders(grid));\\n  };\\n  for (const k of ["col_grid", "row_grid", "data", "row_paths", "col_paths"]) model.on(`change:${k}`, scheduleDraw);\\n  for (const k of ["cell_width", "cell_height"]) model.on(`change:${k}`, resize);\\n  model.on("change:selected", paintSelection);\\n  draw();\\n}\\n\\nexport default { render };\\n\'\n    _css = \'/* MultilevelTable v2 — CSS Grid renderer.\\n   No external font or network requests: IBM Plex is used if installed,\\n   otherwise the system UI font. */\\n\\n.mlt-root {\\n  --mlt-cell-w: 96px;          /* overridden from Python (cell_width)  */\\n  --mlt-cell-h: 48px;          /* overridden from Python (cell_height) */\\n\\n  --mlt-paper: #f7f5ef;\\n  --mlt-paper-alt: #f1eee5;\\n  --mlt-ink: #20201d;\\n  --mlt-line: #d6d1c4;\\n  --mlt-line-strong: #b3ac99;\\n  --mlt-accent: #16706b;\\n  --mlt-cream: #f3f0e7;\\n  --mlt-lvl0: #2b2a26;\\n  --mlt-lvl1: #56544b;\\n  --mlt-lvl2: #9c9683;\\n  --mlt-lvl3: #e4e0d4;\\n\\n  font-family: \\\'IBM Plex Sans\\\', ui-sans-serif, system-ui, -apple-system, \\\'Segoe UI\\\', sans-serif;\\n  font-size: 12px;\\n  color: var(--mlt-ink);\\n}\\n\\n.mlt-scroll {\\n  overflow: auto;\\n  width: fit-content;          /* hug the grid instead of filling the page */\\n  max-width: 100%;\\n  max-height: 75vh;\\n  border: 1px solid var(--mlt-line-strong);\\n  border-radius: 4px;\\n  background: var(--mlt-paper);\\n}\\n\\n/* position: relative makes the grid the offsetParent, so the sticky\\n   offsets measured in JS are relative to the grid, not the page. */\\n.mlt-grid { display: grid; width: max-content; position: relative; }\\n\\n/* ── Shared cell chrome ─────────────────────────────────────── */\\n.mlt-h, .mlt-cell, .mlt-corner {\\n  box-sizing: border-box;\\n  border-right: 1px solid var(--mlt-line);\\n  border-bottom: 1px solid var(--mlt-line);\\n  min-width: 0;\\n}\\n\\n/* ── Header cells ───────────────────────────────────────────── */\\n.mlt-h {\\n  display: flex;\\n  align-items: center;\\n  gap: 6px;\\n  padding: 5px 8px;\\n  font-weight: 500;\\n  line-height: 1.25;\\n  user-select: none;\\n}\\n\\n/* Column headers: centred, labels wrap onto several lines. */\\n.mlt-h-col {\\n  position: sticky;            /* top offset set per row in JS */\\n  z-index: 2;\\n  justify-content: center;\\n  text-align: center;\\n  white-space: normal;\\n  overflow-wrap: break-word;\\n  hyphens: auto;\\n}\\n.mlt-h-col .mlt-label { min-width: 0; }\\n\\n/* Row headers: one line, sized to content, pinned left. */\\n.mlt-h-row {\\n  position: sticky;            /* left offset set per column in JS */\\n  z-index: 1;\\n  white-space: nowrap;\\n  padding: 0 10px;\\n}\\n\\n.mlt-lvl-0 { background: var(--mlt-lvl0); color: var(--mlt-cream); font-weight: 600;\\n             letter-spacing: 0.04em; text-transform: uppercase; font-size: 11px; }\\n.mlt-lvl-1 { background: var(--mlt-lvl1); color: var(--mlt-cream); }\\n.mlt-lvl-2 { background: var(--mlt-lvl2); color: var(--mlt-ink); }\\n.mlt-lvl-3 { background: var(--mlt-lvl3); color: var(--mlt-ink); }\\n\\n/* Merge / split affordances (column headers only). */\\n.mlt-mergeable, .mlt-splittable {\\n  cursor: pointer;\\n  transition: background-color 120ms ease, color 120ms ease;\\n}\\n.mlt-mergeable:hover, .mlt-splittable:hover { background: var(--mlt-accent); color: #fff; }\\n.mlt-splittable { box-shadow: inset 0 3px 0 var(--mlt-accent); }\\n\\n.mlt-glyph {\\n  flex: none;\\n  display: inline-flex;\\n  align-items: center;\\n  justify-content: center;\\n  width: 14px;\\n  height: 14px;\\n  border-radius: 2px;\\n  font-family: \\\'IBM Plex Mono\\\', ui-monospace, monospace;\\n  font-size: 12px;\\n  background: rgba(0, 0, 0, 0.10);\\n}\\n.mlt-mergeable:hover .mlt-glyph, .mlt-splittable:hover .mlt-glyph { background: rgba(255, 255, 255, 0.3); }\\n\\n/* ── Corner ─────────────────────────────────────────────────── */\\n.mlt-corner {\\n  position: sticky;\\n  top: 0;\\n  left: 0;\\n  z-index: 3;\\n  background: var(--mlt-cream);\\n  border-right-color: var(--mlt-line-strong);\\n  border-bottom-color: var(--mlt-line-strong);\\n}\\n\\n/* ── Data cells ─────────────────────────────────────────────── */\\n.mlt-cell {\\n  position: relative;\\n  overflow: hidden;\\n  padding: 0;\\n  background: var(--mlt-paper);\\n  cursor: pointer;\\n  display: flex;\\n  align-items: center;\\n  justify-content: center;\\n}\\n.mlt-cell > svg { display: block; width: 100%; height: 100%; }\\n\\n.mlt-text {\\n  font-family: \\\'IBM Plex Mono\\\', ui-monospace, monospace;\\n  font-size: 12px;\\n  padding: 0 6px;\\n  white-space: nowrap;\\n  overflow: hidden;\\n  text-overflow: ellipsis;\\n}\\n\\n.mlt-note { padding: 12px 16px; color: var(--mlt-lvl1); }\\n\\n.mlt-empty::after { content: "\\\\00B7"; color: var(--mlt-line-strong); }\\n.mlt-bad { color: #b42318; font-weight: 600; }\\n\\n.mlt-cell:hover { filter: brightness(0.97); }\\n/* Drawn on an overlay: a full-bleed SVG would paint over an inset shadow. */\\n.mlt-selected::after {\\n  content: "";\\n  position: absolute;\\n  inset: 0;\\n  border: 2px solid var(--mlt-accent);\\n  pointer-events: none;\\n}\\n\'\n\n    # --- Python -> browser (render state) ---\n    col_grid = traitlets.Dict().tag(sync=True)\n    row_grid = traitlets.Dict().tag(sync=True)\n    col_paths = traitlets.List().tag(sync=True)\n    row_paths = traitlets.List().tag(sync=True)\n    data = traitlets.List().tag(sync=True)\n    cell_width = traitlets.Int(96).tag(sync=True)\n    cell_height = traitlets.Int(48).tag(sync=True)\n\n    # --- Two-way (the browser sets these) ---\n    col_merged = traitlets.List(traitlets.Unicode()).tag(sync=True)\n    selected = traitlets.Dict(allow_none=True, default_value=None).tag(sync=True)\n\n    def __init__(\n        self,\n        row_headers: HeaderNode | list[HeaderNode],\n        col_headers: HeaderNode | list[HeaderNode],\n        calculate: CalculateFn | None = None,\n        *,\n        cell_width: int = 96,\n        cell_height: int = 48,\n        **kwargs,\n    ):\n        self._row_roots = _as_forest(row_headers)\n        self._col_roots = _as_forest(col_headers)\n        self._calculate = calculate or (lambda r, c: None)\n        super().__init__(cell_width=cell_width, cell_height=cell_height, **kwargs)\n        self._refresh()\n\n    # ------------------------------------------------------------------\n    # Programmatic API\n    # ------------------------------------------------------------------\n\n    def merge(self, key: str) -> None:\n        """Merge a column header. Raises if the key is unknown, is a row\n        header, or the node can\'t be merged in its current state."""\n        self._col_node_or_raise(key).merge()\n        self._refresh()\n\n    def split(self, key: str) -> None:\n        """Split a merged column header."""\n        self._col_node_or_raise(key).split()\n        self._refresh()\n\n    def relabel(self, key: str, label: str) -> None:\n        """Rename any header (row or column). Python-only in v2."""\n        node = find_node(self._col_roots, key) or find_node(self._row_roots, key)\n        if node is None:\n            raise KeyError(f"No header node with key {key!r}")\n        node.relabel(label)\n        self._refresh()\n\n    def select(self, row_key: str, col_key: str) -> None:\n        """Select the cell at a row leaf and a column leaf."""\n        row = _path_ending(self.row_paths, row_key)\n        col = _path_ending(self.col_paths, col_key)\n        if row is None or col is None:\n            raise KeyError(f"No current cell at ({row_key!r}, {col_key!r})")\n        self.selected = {"row": row, "col": col}\n\n    def clear_selection(self) -> None:\n        self.selected = None\n\n    # ------------------------------------------------------------------\n    # Browser-driven changes\n    # ------------------------------------------------------------------\n\n    @traitlets.observe("col_merged")\n    def _on_col_merged(self, change) -> None:\n        if getattr(self, "_syncing", False):\n            return\n        wanted = set(change["new"])\n        current = set(self._merged_keys())\n        if wanted == current:\n            return\n\n        # Splits first, shallowest first, so children reappear before any\n        # further decisions about them.\n        for key in self._ordered(current - wanted, deepest_first=False):\n            node = find_node(self._col_roots, key)\n            if node is not None and node.can_split:\n                node.split()\n        # Then merges, deepest first, so a parent only merges once its\n        # children are leaves.\n        for key in self._ordered(wanted - current, deepest_first=True):\n            node = find_node(self._col_roots, key)\n            if node is not None and node.can_merge:\n                node.merge()\n        # Invalid requests are dropped; _refresh writes back the true state.\n        self._refresh()\n\n    @traitlets.observe("selected")\n    def _on_selected(self, change) -> None:\n        sel = change["new"]\n        if sel is not None and not self._selection_is_current(sel):\n            self.selected = None\n\n    # ------------------------------------------------------------------\n    # Internals\n    # ------------------------------------------------------------------\n\n    def _col_node_or_raise(self, key: str) -> HeaderNode:\n        node = find_node(self._col_roots, key)\n        if node is None:\n            if find_node(self._row_roots, key) is not None:\n                raise ValueError(f"{key!r} is a row header; only column headers can be merged or split")\n            raise KeyError(f"No column header with key {key!r}")\n        return node\n\n    def _merged_keys(self) -> list[str]:\n        return [n.key for r in self._col_roots for n in r.all_nodes() if n.merged]\n\n    def _ordered(self, keys: set[str], *, deepest_first: bool) -> list[str]:\n        depth = {}\n\n        def walk(node: HeaderNode, d: int) -> None:\n            depth[node.key] = d\n            for c in node.children:\n                walk(c, d + 1)\n\n        for r in self._col_roots:\n            walk(r, 0)\n        known = [k for k in keys if k in depth]\n        return sorted(known, key=lambda k: depth[k], reverse=deepest_first)\n\n    def _selection_is_current(self, sel: dict) -> bool:\n        return (\n            isinstance(sel, dict)\n            and sel.get("row") in self.row_paths\n            and sel.get("col") in self.col_paths\n        )\n\n    def _refresh(self) -> None:\n        """Recompute everything the browser draws and push it."""\n        row_paths = leaf_key_paths(self._row_roots)\n        col_paths = leaf_key_paths(self._col_roots)\n\n        row_grid = compute_row_header_grid(self._row_roots).to_dict()\n        for cell in row_grid["cells"]:          # rows are never mergeable\n            cell["canMerge"] = False\n            cell["canSplit"] = False\n\n        data = [[_cell_value(self._calculate(rp, cp)) for cp in col_paths] for rp in row_paths]\n\n        with self.hold_sync():\n            self._syncing = True\n            try:\n                self.col_grid = compute_col_header_grid(self._col_roots).to_dict()\n                self.row_grid = row_grid\n                self.row_paths = row_paths\n                self.col_paths = col_paths\n                self.data = data\n                self.col_merged = self._merged_keys()\n            finally:\n                self._syncing = False\n            if self.selected is not None and not self._selection_is_current(self.selected):\n                self.selected = None\n\n\ndef _cell_value(v: Any) -> Any:\n    """Keep JSON-native values; stringify anything else."""\n    if v is None or isinstance(v, (str, int, float, bool)):\n        return v\n    return str(v)\n\n\ndef _path_ending(paths: list[list[str]], key: str) -> list[str] | None:\n    for p in paths:\n        if p and p[-1] == key:\n            return p\n    return None\n\n\ndef _as_forest(headers: HeaderNode | list[HeaderNode]) -> list[HeaderNode]:\n    if isinstance(headers, HeaderNode):\n        return [headers]\n    return list(headers)\n'
